def integrate_chapters():
    """Main integration function"""
    json_path = Path("/Users/arpanshukla/Desktop/OS/Spiritual Gita/data/bhagavad_gita_shlokas.json")
    
    with open(json_path, 'r', encoding='utf-8') as f:
        data = json.load(f)
    
    # Update chapters 3-10
    for ch in data['chapters']:
        ch_num = ch['chapter_number']
        
        if ch_num in CHAPTERS_DATA:
            # Clear existing shlokas
            ch['shlokas'] = []
            
            # Add new shlokas
            for verse_data in CHAPTERS_DATA[ch_num]:
                shloka = {
                    "verse_number": verse_data['verse_number'],
                    "sanskrit": verse_data['sanskrit'],
                    "english": verse_data['english'],
                    "hindi": verse_data.get('hindi', ''),
                    "kannada": verse_data.get('kannada', ''),
                    "explanation": verse_data.get('explanation', ''),
                    "categories": verse_data.get('categories', [])
                }
                ch['shlokas'].append(shloka)
            
            # Update shloka count
            ch['total_shlokas'] = len(ch['shlokas'])
            print(f"✓ Chapter {ch_num:2d}: Added {len(ch['shlokas']):2d} verses")
    
    # Update metadata
    total_shlokas = sum(ch['total_shlokas'] for ch in data['chapters'])
    if 'metadata' in data:
        data['metadata']['total_shlokas'] = total_shlokas
        data['metadata']['total_chapters'] = len(data['chapters'])
    
    # Save
    with open(json_path, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    
    print(f"\n✓ Integration complete!")
    print(f"✓ Total shlokas: {total_shlokas}")
    return True

if __name__ == "__main__":
    print("Bhagavad Gita Chapters 3-10 Integration")
    print("=" * 60)
    integrate_chapters()
